 theory=[
  ("Qaytgan yorug‘likdagi shart", r"<p>Qaytgan yorug‘likda linzaning pastki sirtidan va plastinaning yuqori sirtidan qaytgan nurlar interferensiyalanadi. Optik jihatdan zichroq muhitdan (shishadan) qaytishda faza \(\pi\) ga sakraydi, shuning uchun yo‘llar farqi \(\Delta=2h+\lambda/2\).</p>"),
  ("Qorong‘i halqalar", r"<p>Qorong‘i halqalar: \(2h=k\lambda\) ⇒ \(r_k^2=kR\lambda\) (\(k=0,1,2,\ldots\)) — markaz qorong‘i. Yorug‘ halqalar: \(r_k^2=(k-\tfrac12)R\lambda\). Ikki sirtdan qaytgan nurlar intensivligi yaqin bo‘lgani uchun kontrast yuqori — o‘lchash qulay.</p>$$R=\frac{D_m^2-D_n^2}{4(m-n)\lambda}.$$"),
  ("Plastinaning egriligi va sifat nazorati", r"<p>Halqalar aylana emas, ellips bo‘lsa — linza yoki plastina sirti noideal (astigmatik). Optik ustaxonalarda etalon shisha bilan aynan shu usulda sirt aniqligi tekshiriladi.</p>")],
 proc=["Mikroskopni yarimshaffof plastina orqali yuqoridan yoriting; filtrni qo‘ying.", "Markaziy qorong‘i dog‘ni topib, okulyar-mikrometr ipini unga to‘g‘rilang.", "Ipni chapga surib, 12-qorong‘i halqagacha sanang; so‘ng o‘ngga yurib, har bir halqa koordinatasini yozing (lyuftni yo‘qotish uchun bir yo‘nalishda).", r"\(D_k\) va \(D_k^2\) ni hisoblang, grafik chizing.", r"\(R\) ni toping va o‘tgan yorug‘likdagi natija bilan solishtiring.", "Filtrni almashtirib (yoki natriy lampa bilan), bir xil halqalar radiuslari nisbatidan to‘lqin uzunliklari nisbatini tekshiring."],
 tbl=(["k", "x_chap, mm", "x_o‘ng, mm", "D_k, mm", "D_k², mm²"], 8),
 calc=r"<p>\(R=\dfrac{D_m^2-D_n^2}{4(m-n)\lambda}\). Bir necha juftlik bo‘yicha o‘rtacha va Styudent usulida tasodifiy xatolik.</p>",
 example=(r"\(\lambda=546\) nm, 4- va 9-qorong‘i halqalar radiuslari 1,55 mm va 2,33 mm. \(R\) ni toping.",
  r"\(R=(2{,}33^2-1{,}55^2)/(5\cdot546\cdot10^{-6})\) mm \(=(5{,}429-2{,}403)/0{,}00273=1108\) mm ≈ 1,11 m."),
 simtask=["Rejimni “qaytgan”ga o‘tkazib, markaziy qorong‘i dog‘ va halqalar kontrastini kuzating.", r"\(R\) ni 2 marta oshiring: \(k\)-halqa radiusi necha marta ortadi?", "Yashil (546 nm) va sariq (589 nm) yorug‘lik uchun 10-halqa radiuslari nisbatini toping."],
 safety=["Simob lampasi ultrabinafsha nurlanish chiqaradi — himoya qopqog‘i va filtr bilan ishlating, nurga tik qaramang.", "Lampa uzoq vaqt qiziydi; o‘chirilgach 10 daqiqa tegmang.", "Optik sirtlarni ushlamang."],
