  (r"Natriyning yorqin sariq chizig‘i:", ["≈ 589 nm", "≈ 656 nm", "≈ 546 nm", "≈ 436 nm"], 0, "D-dublet."),
  (r"Foton energiyasi:", [r"\(E=h\nu=hc/\lambda\)", r"\(E=mc\)", r"\(E=h/\lambda\)", r"\(E=kT\)"], 0, "Plank formulasi."),
  (r"Siyraklashgan gaz qanday spektr beradi?", ["chiziqli", "tutash", "yo‘lli (polosali) faqat", "spektr bermaydi"], 0, "Alohida atomlar."),
  (r"Ridberg doimiysi (vodorod):", [r"\(1{,}097\cdot10^7\) m⁻¹", r"\(6{,}63\cdot10^{-34}\) J·s", r"\(1{,}6\cdot10^{-19}\) Kl", r"\(3\cdot10^8\) m/s"], 0, "Jadval qiymati."),
  (r"Prizmali spektroskop shkalasi:", ["chiziqli emas — darajalash kerak", "chiziqli", "logarifmik", "har doim nm da"], 0, "Prizma dispersiyasi to‘lqin uzunligiga bog‘liq."),
